// Pray to the youtube DOM god that it works first try(Spoiler: it doesn't)
// Whoever stumbles upon this code, I'm sorry for what you're about to witness


// Track initialized emoji pickers to avoid duplicate setup
const initializedPickers = new WeakSet();

// ridiculously long SVG data URIs for white and black pixels(fuck Adobe)
const whiteSVG = `data:img/png;base64,`;
const graySVG = `data:img/png;base64,`;

// Function to initialize a single emoji picker
async function initializeEmojiPicker(mainContainer) {
    // Skip if already initialized
    if (initializedPickers.has(mainContainer)) {
        return;
    }
    initializedPickers.add(mainContainer);

    const emojiPanel = mainContainer.querySelector("#emojis > #emoji-picker > #emoji");
    const buttonsDiv = emojiPanel.querySelector("#category-buttons");
    const emojiButton = mainContainer.querySelector("#main #emoji-button");

    // Crazy query, I know 💀
    if (emojiButton) {
        const icon = emojiButton.querySelector("ytd-button-renderer > yt-button-shape > button > div > span > span");
        
        if (icon && icon.innerHTML.trim() === '') {
            // This is such a cooked solution just to change the damn icon bruh...
            const iconObserver = new MutationObserver((mutationsList, observer) => {
                if(icon.innerHTML.trim() !== '') {
                    icon.classList.add('loaded');
                    observer.disconnect();

                    icon.innerHTML = `
                        <svg 
                            xmlns="http://www.w3.org/2000/svg"
                            xmlns:xlink="http://www.w3.org/1999/xlink"
                            width="24px" height="24px">
                            <image x="0px" y="0px" width="24px" height="24px" xlink:href="${whiteSVG}"/>
                        </svg>
                    `;
                    icon.style.transform = "RotateZ(-2deg)";
                }
            });
            iconObserver.observe(icon, { childList: true });
        } else if (icon && icon.innerHTML.trim() !== '' && !icon.classList.contains('loaded')) {
            icon.classList.add('loaded');
            icon.innerHTML = `
                <svg 
                    xmlns="http://www.w3.org/2000/svg"
                    xmlns:xlink="http://www.w3.org/1999/xlink"
                    width="24px" height="24px">
                    <image x="0px" y="0px" width="24px" height="24px" xlink:href="${whiteSVG}"/>
                </svg>
            `;
            icon.style.transform = "RotateZ(-2deg)";
        }
    }

    // Wait for category buttons to be ready
    const categoryButtons = buttonsDiv.querySelector("yt-emoji-picker-category-button-renderer");
    if (!categoryButtons) {
        initializedPickers.delete(mainContainer);
        return;
    }

    // Get elements specific to this picker instance
    const emojiInput = emojiPanel.querySelector("#search-panel tp-yt-iron-input > input");
    const searchCategory = emojiPanel.querySelector('#search-category > #emoji');
    const searchEmpty = emojiPanel.querySelector('#search-empty');
    const commentField = mainContainer.querySelector("#main #contenteditable-root");

    const buttonContainer = buttonsDiv.appendChild(document.createElement("yt-emoji-picker-category-button-renderer"));
    buttonContainer.classList.add("style-scope", "yt-emoji-picker-renderer");
    buttonContainer.id = "swarmTube";

    const buttonIcon = buttonContainer.appendChild(document.createElement("yt-icon-button"));
    buttonIcon.classList.add("style-scope", "yt-emoji-picker-category-button-renderer");
    buttonIcon.id = "button";

    const button = buttonIcon.appendChild(document.createElement("button"));
    button.classList.add("style-scope", "yt-icon-button");
    button.id = "button";
    button.setAttribute("aria-label", "swarmTube");

    // WHY THE FUCK DO YOU NEED SO MANY OF THOSE DAM TAGS YOUTUBE 😭😭😭
    const icon = button.appendChild(document.createElement("yt-icon"));
    icon.classList.add("style-scope", "yt-icon-shape", "yt-icon", "ytSpecIconShapeHost");

    const randomAssDiv = icon.appendChild(document.createElement("div"));
    randomAssDiv.style = `width: 100%; height: 100%; display: block; fill: currentcolor;`;

    randomAssDiv.innerHTML = `
        <svg 
            xmlns="http://www.w3.org/2000/svg"
            xmlns:xlink="http://www.w3.org/1999/xlink"
            width="18px" height="18px">
            <image x="0px" y="0px" width="18px" height="18px" xlink:href="${graySVG}"/>
        </svg>
    `;

    const categories = mainContainer.querySelector('#categories');
    const swarmTubeCategory = categories.appendChild(document.createElement('yt-emoji-picker-category-renderer'));
    swarmTubeCategory.classList.add('style-scope', 'yt-emoji-picker-renderer');
    swarmTubeCategory.setAttribute('role', 'listbox');
    swarmTubeCategory.setAttribute('aria-label', 'swarmTube');
    swarmTubeCategory.setAttribute('tabindex', '0');

    const categoryHeader = swarmTubeCategory.appendChild(document.createElement('yt-formatted-string'));
    categoryHeader.id = 'title';
    categoryHeader.classList.add("style-scope", "yt-emoji-picker-category-renderer");
    categoryHeader.textContent = 'swarmTube';

    const emojisGrid = swarmTubeCategory.appendChild(document.createElement('div'));
    emojisGrid.id = 'emoji';
    emojisGrid.classList.add('CATEGORY_TYPE_UNICODE', 'style-scope', 'yt-emoji-picker-category-renderer', 'style-scope', 'yt-emoji-picker-category-renderer');
    emojisGrid.setAttribute('role', 'listbox');
    emojisGrid.setAttribute('aria-label', 'swarmTube');

    const emoteResponse = await ext.runtime.sendMessage({ type: "GET_7TV_EMOTES" });

    emoteResponse.emotes.forEach(emote => {
        const emoteButton = emojisGrid.appendChild(document.createElement('img'));
        emoteButton.classList.add('style-scope', 'yt-emoji-picker-category-renderer');
        emoteButton.id = emote.name;
        emoteButton.height = 24;
        emoteButton.width = 24;
        emoteButton.src = emote.url;
        emoteButton.loading = 'lazy';
        emoteButton.alt = emote.name;
        emoteButton.setAttribute('role', 'option');
        emoteButton.setAttribute('aria-label', emote.name);
        emoteButton.setAttribute('aria-selected', 'false');

        // Is Youtube drunk while coding their emoji picker or what. Why they need mouseover when there's no children elements???
        emoteButton.addEventListener('mouseover', (e) => {
            e.stopPropagation();
        });

        emoteButton.addEventListener('mouseenter', (e) => {
            emoteButton.style.transform = 'scale(1.2)';
            emoteButton.style.transition = 'transform 0.2s ease';

            emojiInput.placeholder = `:${emote.name}:`;
        });
        
        emoteButton.addEventListener('mouseleave', (e) => {
            emoteButton.style.transform = 'scale(1)';
            emojiInput.placeholder = 'Search emoji';
        });

        emoteButton.addEventListener('mousedown', (e) => {
            e.stopPropagation();
            e.preventDefault();
        });
        // Using mousedown and click at the same time??? Youtube what the fuck. I might be too dumb to understand this.
        emoteButton.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();

            commentField.focus();
            const selection = window.getSelection();
            const range = selection.getRangeAt(0);

            const textNode = document.createTextNode(`${emote.name} `);

            range.deleteContents();
            range.insertNode(textNode);

            range.setStartAfter(textNode);
            range.setEndAfter(textNode);
            selection.removeAllRanges();
            selection.addRange(range);

            commentField.dispatchEvent(new Event('input', { bubbles: true }));
        });
    });

    buttonContainer.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        
        // Scroll to SwarmTube category
        const targetPosition = swarmTubeCategory.offsetTop - categories.offsetTop;
        categories.scrollTo({
            top: targetPosition,
            behavior: 'smooth'
        });

        // Weird ass Youtube error prevention (doesn't work btw)
        const svgImage = randomAssDiv.querySelector('image');
        if (svgImage) {
            svgImage.addEventListener('mousedown', (event) => {
                event.stopPropagation();
                event.preventDefault();
            });
            svgImage.addEventListener('mouseup', (event) => {
                event.stopPropagation();
                event.preventDefault();
            });
        }

        
    });

    // Deactivate SwarmTube button when other buttons are clicked
    Array.from(buttonsDiv.children).forEach(btn => {
        if (btn !== buttonContainer) {
            btn.addEventListener('click', () => {
                buttonContainer.removeAttribute('active');
                randomAssDiv.innerHTML = `
                    <svg 
                        xmlns="http://www.w3.org/2000/svg"
                        xmlns:xlink="http://www.w3.org/1999/xlink"
                        width="18px" height="18px">
                        <image x="0px" y="0px" width="18px" height="18px" xlink:href="${graySVG}"/>
                    </svg>
                `;
            });
        }
    });

    // Observe when SwarmTube category scrolls into view
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                // Category is in view
                Array.from(buttonsDiv.children).forEach(btn => {
                    if (btn !== buttonContainer) {
                        btn.removeAttribute('active');
                    }
                });
                buttonContainer.setAttribute('active', '');
                randomAssDiv.innerHTML = `
                    <svg 
                        xmlns="http://www.w3.org/2000/svg"
                        xmlns:xlink="http://www.w3.org/1999/xlink"
                        width="18px" height="18px">
                        <image x="0px" y="0px" width="18px" height="18px" xlink:href="${whiteSVG}"/>
                    </svg>
                `;
            } else {
                // Category is out of view
                buttonContainer.removeAttribute('active');
                randomAssDiv.innerHTML = `
                    <svg 
                        xmlns="http://www.w3.org/2000/svg"
                        xmlns:xlink="http://www.w3.org/1999/xlink"
                        width="18px" height="18px">
                        <image x="0px" y="0px" width="18px" height="18px" xlink:href="${graySVG}"/>
                    </svg>
                `;
            }
        });
    }, {
        root: categories, 
        threshold: 1 
    });
    observer.observe(categoryHeader);

    let currentSearchId = 0; // Track the current search to prevent race conditions(fuck timings)
    
    emojiInput.addEventListener('input', async () => {
        const query = emojiInput.value.toLowerCase();
        const searchId = ++currentSearchId; // Increment and capture current search ID
        
        // Clear previous 7TV suggestions immediately
        const swarmTubeEmotes = searchCategory.querySelectorAll('img.swarmTube-emote');
        swarmTubeEmotes.forEach(emote => emote.remove());
        
        if (query.length === 0) return;

        const sugResponse = await ext.runtime.sendMessage({ type: "GET_EMOTE_SUGGESTIONS", query: query });
        
        // Check if this search is still the latest one
        if (searchId !== currentSearchId) {
            return;
        }
        
        const suggestions = sugResponse.suggestions;

        if (suggestions.length === 0) {
            searchEmpty.style.display = 'block';
        } else {
            searchEmpty.style.display = 'none';
        }

        suggestions.forEach(element => {
            const emoteElem = searchCategory.appendChild(document.createElement('img'));
            emoteElem.classList.add('style-scope', 'yt-emoji-picker-category-renderer', 'swarmTube-emote');
            emoteElem.id = element.name;
            emoteElem.height = 24;
            emoteElem.width = 24;
            emoteElem.src = element.url;
            emoteElem.loading = 'lazy';
            emoteElem.alt = element.name;
            emoteElem.setAttribute('role', 'option');
            emoteElem.setAttribute('aria-label', element.name);
            emoteElem.setAttribute('aria-selected', 'false');


            emoteElem.addEventListener('mouseover', (e) => {
                e.stopPropagation();
            });

            emoteElem.addEventListener('mouseenter', (e) => {
                emoteElem.style.transform = 'scale(1.2)';
                emoteElem.style.transition = 'transform 0.2s ease';

                emojiInput.placeholder = `:${emoteElem.alt}:`;
            });
            
            emoteElem.addEventListener('mouseleave', (e) => {
                emoteElem.style.transform = 'scale(1)';
                emojiInput.placeholder = 'Search emoji';
            });

            emoteElem.addEventListener('mousedown', (e) => {
                e.stopPropagation();
                e.preventDefault();
            });

            emoteElem.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();

                commentField.focus();
                const selection = window.getSelection();
                const range = selection.getRangeAt(0);

                const textNode = document.createTextNode(`${emoteElem.alt} `);

                range.deleteContents();
                range.insertNode(textNode);

                range.setStartAfter(textNode);
                range.setEndAfter(textNode);
                selection.removeAllRanges();
                selection.addRange(range);

                commentField.dispatchEvent(new Event('input', { bubbles: true }));
            });

        });
    });
}

// Continuously monitor for new emoji pickers
const pickerObserver = new MutationObserver((mutations) => {
    const emojiPickers = document.querySelectorAll('#commentbox');
    emojiPickers.forEach(picker => {
        initializeEmojiPicker(picker);
    });
});

pickerObserver.observe(document.body, {
    childList: true,
    subtree: true
});

// Initialize any existing emoji pickers
const existingPickers = document.querySelectorAll('#commentbox');
existingPickers.forEach(picker => {
    initializeEmojiPicker(picker);
});